  const rounds: MessageChunk[][] = [
    [{type: 'tool_use', toolCall: {id: 'call-bad', name: 'lookup_ticket', input: {}}}, STOP_FOR_TOOL],
    [
      {type: 'tool_use', toolCall: {id: 'call-good', name: 'lookup_ticket', input: {ticketId: 'INC-42'}}},
      STOP_FOR_TOOL,
    ],
