  ];
  let currentRound = 0;
  const provider: AIProvider = {
    async *sendMessage(params: SendMessageParams): AsyncGenerator<MessageChunk> {
      roundSnapshots.push(JSON.stringify(params.messages));
      for (const chunk of rounds[currentRound++] ?? []) yield chunk;
    },
    async generateStructured(): Promise<never> {
      throw new Error('unused');
    },
  };
  const executedInputs: Array<Record<string, unknown>> = [];
  const registry = new ToolRegistry();
